const recordLoginFailure = `-- name: RecordLoginFailure :exec
update users
   set failed_logins = failed_logins + 1,
       locked_until = case when failed_logins + 1 >= $1::int
                           then now() + $2::interval else locked_until end
 where id = $3
`

type RecordLoginFailureParams struct {
	MaxFailures int32           `json:"max_failures"`
	LockFor     pgtype.Interval `json:"lock_for"`
	ID          pgtype.UUID     `json:"id"`
}

// After max_failures consecutive failures the account locks for lock_for.
func (q *Queries) RecordLoginFailure(ctx context.Context, arg RecordLoginFailureParams) error {
	_, err := q.db.Exec(ctx, recordLoginFailure, arg.MaxFailures, arg.LockFor, arg.ID)
	return err
}

const reserveRun = `-- name: ReserveRun :one
insert into organization_usage (org_id, month, runs)
values ($1, date_trunc('month', now() at time zone 'utc')::date, 1)
on conflict (org_id, month) do update set runs = organization_usage.runs + 1
 where $2::bigint <= 0 or organization_usage.runs < $2::bigint
returning runs
`

type ReserveRunParams struct {
	OrgID   pgtype.UUID `json:"org_id"`
	MaxRuns int64       `json:"max_runs"`
}

// Counts one run against the current month. With a limit, the update only
// applies while runs < limit, so concurrent starts cannot overshoot it: no row
// comes back once the allowance is used up.
func (q *Queries) ReserveRun(ctx context.Context, arg ReserveRunParams) (int64, error) {
	row := q.db.QueryRow(ctx, reserveRun, arg.OrgID, arg.MaxRuns)
	var runs int64
	err := row.Scan(&runs)
	return runs, err
}

